/**
 * @suppress
 */
public object FfiConverterTypeBridge: FfiConverter<Bridge, Long> {
    override fun lower(value: Bridge): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Bridge {
        return Bridge(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Bridge {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Bridge) = 8UL

    override fun write(value: Bridge, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



