/**
 * Why a bridge call failed. Kotlin renders these in the trace, never
 * silently swallows them.
 */
sealed class BridgeException: kotlin.Exception() {
    
    class Store(
        
        val `msg`: kotlin.String
        ) : BridgeException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    class NoStore(
        ) : BridgeException() {
        override val message
            get() = ""
    }
    
    class NoCore(
        ) : BridgeException() {
        override val message
            get() = ""
    }
    
    class Io(
        
        val `msg`: kotlin.String
        ) : BridgeException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BridgeException> {
        override fun lift(error_buf: RustBuffer.ByValue): BridgeException = FfiConverterTypeBridgeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeBridgeError : FfiConverterRustBuffer<BridgeException> {
    override fun read(buf: ByteBuffer): BridgeException {
        

        return when(buf.getInt()) {
            1 -> BridgeException.Store(
                FfiConverterString.read(buf),
                )
            2 -> BridgeException.NoStore()
            3 -> BridgeException.NoCore()
            4 -> BridgeException.Io(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BridgeException): ULong {
        return when(value) {
            is BridgeException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is BridgeException.NoStore -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.NoCore -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: BridgeException, buf: ByteBuffer) {
        when(value) {
            is BridgeException.Store -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is BridgeException.NoStore -> {
                buf.putInt(2)
                Unit
            }
            is BridgeException.NoCore -> {
                buf.putInt(3)
                Unit
            }
            is BridgeException.Io -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




